SELECT COUNT(0) FROM ${collection} WHERE id = #{id}
AND deleted_at IS NULL
AND deleted_at IS NOT NULL

SELECT
    data_id           AS dataId,
    subject_id        AS subjectId,
    subject_type      AS subjectType,
    action            AS action,
    attributes        AS attributes
FROM
    ${collection}
WHERE
    data_id = #{dataId}
    AND (
           (
            subject_id = '*'
            AND subject_type = 1
        )

        OR (
            subject_id = #{ownerId}
            AND subject_type = 1
        )


        OR (
            subject_id = #{departmentId}
            AND subject_type = 2
        )


        OR (
            subject_id IN

               #{teamId}

            AND subject_type = 3
        )


        OR (
            subject_id IN

               #{roleNm}

            AND subject_type = 4
        )

    )
    AND action >= #{action}

mapper.delete:
DELETE FROM
    ${collection}
WHERE
    data_id = #{dataId}

    AND subject_id = #{subjectId}


    AND subject_type = #{subjectType}

mapper.select:
SELECT
    COUNT(DISTINCT data.id)
FROM
    ${dataCollection} data
    LEFT JOIN ${authCollection} auth
           ON data.id = auth.data_id
WHERE
    1 = 1

    AND data.id IN

        #{id}



    AND data.id = #{dataInfo.id}


    AND data.name LIKE CONCAT('%', #{dataInfo.name}, '%')


    AND data.type = #{dataInfo.type}


    AND data.folder = #{dataInfo.folder}


    AND data.`case` = #{dataInfo.cs}


    AND data.template = #{dataInfo.template}


    AND data.system = #{dataInfo.system}


    AND data.shared = #{dataInfo.shared}

    AND (


        data.owner_id = #{ownerId}


        1 = 1



        OR (auth.subject_id = #{userId} AND auth.subject_type = 1)


        OR (auth.subject_id = #{departmentId} AND auth.subject_type = 2)


        OR (
            auth.subject_id IN

                #{teamId}

            AND auth.subject_type = 3
        )

    )

    AND data.owner_id = #{dataInfo.ownerId}


    AND data.owner_name LIKE CONCAT('%', #{dataInfo.ownerName}, '%')


    AND data.department_id = #{dataInfo.departmentId}


    AND (JSON_CONTAINS(data.teams, CONCAT('["', #{dataInfo.teamId}, '"]')))


    AND data.created_at >= STR_TO_DATE(#{dataInfo.createdStartStr}, '%Y-%m-%d %H:%i:%s')



    AND data.created_at <= STR_TO_DATE(#{dataInfo.createdEndStr}, '%Y-%m-%d %H:%i:%s')



    AND data.updated_at >= STR_TO_DATE(#{dataInfo.updatedStartStr}, '%Y-%m-%d %H:%i:%s')



    AND data.updated_at <= STR_TO_DATE(#{dataInfo.updatedEndStr}, '%Y-%m-%d %H:%i:%s')




    AND data.deleted_at IS NULL


    AND data.deleted_at IS NOT NULL

SELECT id AS id, name AS name, image AS image, data AS dataJsonStr, type AS type, folder AS folder, `case` AS cs, template AS template, `system` AS `system`, shared AS shared, recommend AS recommend, owner_id AS ownerId, owner_name AS ownerName, editor_id AS editorId, editor_name AS editorName, department_id AS departmentId, teams AS teams, DATE_FORMAT(created_at, '%Y-%m-%d %H:%i:%s') AS createdAt, DATE_FORMAT(updated_at, '%Y-%m-%d %H:%i:%s') AS updatedAt, DATE_FORMAT(deleted_at, '%Y-%m-%d %H:%i:%s') AS deletedAt FROM ${collection} WHERE id = #{id}
AND owner_id = #{ownerId}
AND shared = TRUE
AND deleted_at IS NULL
AND deleted_at IS NOT NULL

