UPDATE
    ${collection}
SET
    updated_at = CURRENT_TIMESTAMP

    ,name = #{dataInfo.name}


    ,image = #{dataInfo.image}


    ,data = #{dataInfo.dataJsonStr}


    ,type = #{dataInfo.type}


    ,folder = #{dataInfo.folder}


    ,`case` = #{dataInfo.cs}


    ,template = #{dataInfo.template}


    ,`system` = #{dataInfo.system}


    ,shared = #{dataInfo.shared}


    ,recommend = #{dataInfo.recommend}


    ,owner_id = #{dataInfo.ownerId}


    ,owner_name = #{dataInfo.ownerName}


    ,editor_id = #{dataInfo.editorId}


    ,editor_name = #{dataInfo.editorName}


    ,department_id = #{dataInfo.departmentId}


    ,teams = JSON_ARRAY(${dataInfo.teams})

WHERE
    id = #{dataInfo.id}

